import decimal
import numpy as np
def library(decimal_arg):
    if type(decimal_arg) is not decimal.Decimal:
        raise TypeError('Not a decimal.Decimal')
    return decimal_arg
def try_library(arg):
    try:
        print(library(arg))
    except TypeError as e:
        print(e)
def main():
    a = np.float32(1.1)
    b = np.int32(2)
