"""
Logging handler that stores all records to be formatted later
"""
class LoggingHandler(logging.Handler):
    def __init__(self):
        super(LoggingHandler, self).__init__()
        self.records = []

    def emit(self, record):
        self.records.append(record)

"""
Formatter that formats the records to be formatted later
